node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the order - try with and without # prefix
let order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('#ORD-F15D7C');
if (!order) order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('ORD-F15D7C');
if (!order) order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%F15D7C%'\").get();
if (!order) {
  // list all order_ids
  const ids = db.prepare('SELECT order_id FROM orders').all();
  console.log('All order IDs:', JSON.stringify(ids));
} else {
  console.log('ORDER:', JSON.stringify(order, null, 2));
}
"

