node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const productIds = ['PROD-3E35A7', 'PROD-4ED2E3', 'PROD-39F904', 'PROD-FA0948'];
for (const pid of productIds) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  if (product) {
    // Truncate large JSON fields for readability
    console.log('\n=== PRODUCT: ' + pid + ' ===');
    console.log('Name:', product.name);
    console.log('Category:', product.category);
    console.log('Subcategory:', product.subcategory);
    console.log('Brand:', product.brand);
    console.log('Price:', product.price);
    console.log('Current Price:', product.current_price);
    console.log('In Stock:', product.in_stock);
    console.log('Stock Qty:', product.stock_quantity);
    console.log('Rating:', product.rating);
    console.log('Review Count:', product.review_count);
    console.log('Description:', product.description);
    console.log('Shipping Days:', product.shipping_days);
    console.log('Gift Wrap:', product.gift_wrap_available);
    console.log('Backorder:', product.backorder_available);
    console.log('Warranty Months:', product.warranty_months);
    console.log('Return Window Days:', product.return_window_days);
    console.log('Restocking Fee %:', product.restocking_fee_pct);
    console.log('Weight (lbs):', product.weight_lbs);
    console.log('Fragile:', product.is_fragile);
    console.log('Specs:', product.specs_json);
    console.log('Variants:', product.variants_json);
  } else {
    console.log('Product not found:', pid);
  }
}
"

